effect.shader:
vec4 u_xlat0;
vec4 u_xlat1;
vec2 u_xlat2;
bvec2 u_xlatb2;
vec4 u_xlat3;
vec4 u_xlat4;
vec4 u_xlat5;
float u_xlat12;
int u_xlati14;
float u_xlat18;
int u_xlati18;
float u_xlat20;
bool u_xlatb20;
void main()
{
    u_xlat0.xy = (-acScreenNorm.xy) + _center.xy;
    u_xlat12 = float(int(_samples));
    u_xlat0.xy = u_xlat0.xy / vec2(u_xlat12);
    u_xlati18 = int(_samples) + int(0xFFFFFFFFu);
    u_xlat18 = float(u_xlati18);
    u_xlat1.x = float(0.0);
    u_xlat1.y = float(0.0);
    u_xlat1.z = float(0.0);
    u_xlat1.w = float(0.0);
    u_xlat2.xy = acScreenNorm.xy;
    for(int u_xlati_loop_1 = 0 ; u_xlati_loop_1<int(_samples) ; u_xlati_loop_1++)
    {
        u_xlat3 = texture(inputImg, u_xlat2.xy);
        u_xlat20 = dot(u_xlat3.xyz, vec3(0.300000012, 0.589999974, 0.109999999));
        u_xlatb20 = _threshold<u_xlat20;
        u_xlat4.x = float(u_xlati_loop_1);
        u_xlat4.x = u_xlat4.x / u_xlat18;
        u_xlat4.z = u_xlat4.x * 3.0 + -1.5;
        u_xlat4.y = -abs(u_xlat4.z) + 1.0;
        u_xlat4.x = (-u_xlat4.z);
        u_xlat4.xyz = u_xlat4.xyz;
        u_xlat4.xyz = clamp(u_xlat4.xyz, 0.0, 1.0);
        u_xlat4.xyz = u_xlat3.xyz * u_xlat4.xyz;
        u_xlat4.xyz = u_xlat4.xyz * vec3(3.0, 3.0, 3.0) + (-u_xlat3.xyz);
        u_xlat3.xyz = vec3(_dispersion) * u_xlat4.xyz + u_xlat3.xyz;
        u_xlat3 = u_xlat3 * vec4(vec4(_brightness, _brightness, _brightness, _brightness));
        u_xlat3 = u_xlat3 * _color + u_xlat1;
        u_xlat1 = (bool(u_xlatb20)) ? u_xlat3 : u_xlat1;
        u_xlat2.xy = u_xlat0.xy * vec2(vec2(_amount, _amount)) + u_xlat2.xy;
    }
    u_xlat0 = u_xlat1 / vec4(u_xlat12);
    u_xlat1 = texture(inputImg, acScreenNorm.xy);
    u_xlat0 = u_xlat0 * vec4(vec4(_weight, _weight, _weight, _weight));
    u_xlat0 = u_xlat1 * vec4(_blend) + u_xlat0;
    if(int(_use_inner_mask) != 0) {
        u_xlatb2.xy = equal(ivec4(int(_show_inner_mask), int(_b_clip_mask), int(_show_inner_mask), int(_show_inner_mask)), ivec4(1, 1, 0, 0)).xy;
        u_xlat3 = (u_xlatb2.x) ? vec4(1.0, 0.0, 1.0, 1.0) : u_xlat0;
        u_xlat4 = texture(Mask, acScreenNorm.xy);
        u_xlat5 = (-u_xlat4) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat1 = u_xlat1 * u_xlat5;
        u_xlat1 = u_xlat3 * u_xlat4 + u_xlat1;
        u_xlat2.x = u_xlat4.x * u_xlat1.w;
        fragColor.w = (u_xlatb2.y) ? u_xlat2.x : u_xlat1.w;
        fragColor.xyz = u_xlat1.xyz;
    } else {
        fragColor = u_xlat0;
    }
    return;
}
